```python
class BankAccount:
    def __init__(self, name, initial_balance):
        self.name = name
        self.balance = self.validate_amount(initial_balance)
        self.transactions = [f"Anfängliche Einzahlung von {initial_balance}"]

    def validate_amount(self, amount):
        if amount < 0:
            raise ValueError("Der Betrag darf nicht negativ sein.")
        return amount

    def deposit(self, amount):
        amount = self.validate_amount(amount)
        self.balance += amount
        self.transactions.append(f"Einzahlung von {amount}")

    def withdraw(self, amount):
        amount = self.validate_amount(amount)
        if amount > self.balance:
            print("Unzureichende Guthaben.")
        else:
            self.balance -= amount
            self.transactions.append(f"Auszahlung von {amount}")

    def check_balance(self):
        print(f"Ihr Guthaben beträgt {self.balance:.2f} €")

    def transaction_history(self):
        for transaction in self.transactions:
            print(transaction)

    def transfer(self, amount, recipient):
        amount = self.validate_amount(amount)
        if amount > self.balance:
            print("Unzureichende Guthaben.")
        else:
            self.balance -= amount
            recipient.balance += amount
            self.transactions.append(f"Überweisung von {amount} an {recipient.name}")
            recipient.transactions.append(f"Überweisung von {amount} von {self.name}")

def main():
    name = input("Bitte geben Sie Ihren Namen ein: ")
    while True:
        try:
            initial_balance = float(input("Bitte geben Sie Ihren anfänglichen Einzahlungsbetrag ein: "))
            account = BankAccount(name, initial_balance)
            break
        except ValueError as e:
            print(f"Fehler: {e}. Bitte geben Sie einen gültigen Betrag ein.")

    while True:
        print("\n1. Einzahlung")
        print("2. Auszahlung")
        print("3. Kontostand abfragen")
        print("4. Transaktionsverlauf anzeigen")
        print("5. Überweisung")
        print("6. Beenden")

        choice = input("Bitte wählen Sie eine Option: ")

        if choice == "1":
            while True:
                try:
                    amount = float(input("Bitte geben Sie den Betrag ein, den Sie einzahlen möchten: "))
                    account.deposit(amount)
                    break
                except ValueError as e:
                    print(f"Fehler: {e}. Bitte geben Sie einen gültigen Betrag ein.")
        elif choice == "2":
            while True:
                try:
                    amount = float(input("Bitte geben Sie den Betrag ein, den Sie abheben möchten: "))
                    account.withdraw(amount)
                    break
                except ValueError as e:
                    print(f"Fehler: {e}. Bitte geben Sie einen gültigen Betrag ein.")
        elif choice == "3":
            account.check_balance()
        elif choice == "4":
            account.transaction_history()
        elif choice == "5":
            recipient_name = input("Bitte geben Sie den Namen des Empfängers ein: ")
            recipient_balance = float(input("Bitte geben Sie den anfänglichen Einzahlungsbetrag des Empfängers ein: "))
            recipient = BankAccount(recipient_name, recipient_balance)
            while True:
                try:
                    amount = float(input("Bitte geben Sie den Betrag ein, den Sie überweisen möchten: "))
                    account.transfer(amount, recipient)
                    break
                except ValueError as e:
                    print(f"Fehler: {e}. Bitte geben Sie einen gültigen Betrag ein.")
        elif choice == "6":
            break
        else:
            print("Ungültige Eingabe. Bitte versuchen Sie es erneut.")

if __name__ == "__main__":
    main()
```

### Verbesserungen und Ergänzungen:
