```python
# Wörterbuch zur Speicherung der Bankkonten
bankAccounts = {}

def hauptmenue():
    while True:
        print("\nHauptmenü:")
        print("1. Bankkonto hinzufügen")
        print("2. Bankkonto ändern")
        print("3. Bankkonto löschen")
        print("4. Programm beenden")
        auswahl = input("Bitte wählen Sie eine Option (1-4): ")

        if auswahl == '1':
            bankkonto_hinzufuegen()
        elif auswahl == '2':
            bankkonto_aendern()
        elif auswahl == '3':
            bankkonto_loeschen()
        elif auswahl == '4':
            print("Programm wird beendet.")
            break
        else:
            print("Ungültige Eingabe. Bitte wählen Sie erneut.")

def bankkonto_hinzufuegen():
    kontonummer = input("Bitte geben Sie die Kontonummer ein: ")
    if kontonummer in bankAccounts:
        print("Diese Kontonummer existiert bereits.")
    else:
        kundename = input("Bitte geben Sie den Kundennamen ein: ")
        kontostand = float(input("Bitte geben Sie den Kontostand ein: "))
        bankAccounts[kontonummer] = {'Kundename': kundename, 'Kontostand': kontostand}
        print("Bankkonto erfolgreich hinzugefügt.")

def bankkonto_aendern():
    kontonummer = input("Bitte geben Sie die Kontonummer des zu ändernden Kontos ein: ")
    if kontonummer in bankAccounts:
        kundename = input("Bitte geben Sie den neuen Kundennamen ein: ")
        kontostand = float(input("Bitte geben Sie den neuen Kontostand ein: "))
        bankAccounts[kontonummer] = {'Kundename': kundename, 'Kontostand': kontostand}
        print("Bankkonto erfolgreich geändert.")
    else:
        print("Diese Kontonummer existiert nicht.")

def bankkonto_loeschen():
    kontonummer = input("Bitte geben Sie die Kontonummer des zu löschenden Kontos ein: ")
    if kontonummer in bankAccounts:
        del bankAccounts[kontonummer]
        print("Bankkonto erfolgreich gelöscht.")
    else:
        print("Diese Kontonummer existiert nicht.")

# Hauptprogramm
if __name__ == "__main__":
    hauptmenue()
```

