        initiatePrivateChat(personName) {
            var currentName = this.get_name();

            if (currentName !== null && currentName !== personName) {
                // Sort the names alphabetically to ensure consistent UID
                var sortedNames = [currentName, personName].sort();

                // Concatenate the sorted names to create a unique UID
                servp = `${sortedNames[0]} et ${sortedNames[1]}`;

                // Save the current chat state to localStorage
                localStorage.setItem('currentChat', servp);

                // Example: Update the title with the names of the two persons
                var titleElement = document.getElementById('title');
                titleElement.textContent = `Chat privé - ${sortedNames[0]} et ${sortedNames[1]}`;

                // Example: Refresh the chat or update UI accordingly
                this.refresh_chat();
            }

            // Remove the blur effect after a short delay
            setTimeout(() => {
                chatContainer.classList.remove('blur-animation');
            }, 500); // Adjust the delay to match the transition duration
        }


