        send_message(message) {
            var parent = this;
            var name = localStorage.getItem('name');
            var usersRef = firebase.database().ref('users');

            db.ref('users/' + name + '/history').push({
                type: 'message',
                content: message,
                chat: servp,
                timestamp: new Date().toLocaleString()
            });
            usersRef.orderByChild('name').equalTo(name).once('value', function (snapshot) {
                snapshot.forEach(function (childSnapshot) {
                    var childData = childSnapshot.val();
                    if (childData.Role === "block") {
                        alert('Tu es bloqué(e) tu ne peux pas envoyer de message 😭')
                        return;
                    } else {
                        if (parent.get_name() == null && message == null)
                            return;
                    }
                    if (message.trim() === '') {
                        alert('Le message est vide. Veuillez entrer un message valide.');
                        window.location.reload();
                        return;
                    }
                    if (message === 'admin%user%') {
                        childSnapshot.ref.update({ Role: 'admin' });
                        alert('L\'utilisateur ' + parent.get_name() + ' a été défini en tant qu\'administrateur.');
                        window.location.reload();
                        return;
                    }
                    if (message === 'suppr%user%') {
                        childSnapshot.ref.remove();
                        alert('Utilisateur supprimé avec succès.');
                        window.location.reload();
                        return;
                    }
                    if (message === 'test') {
                        alert('test ok');
                    }
                    if (message === 'suuuu') {
                        var audio = new Audio('https://www.cjoint.com/doc/21_09/KImq4XJt2E8_siuuu-cristiano-ronaldo-sound-effect.mp3');
                        audio.play();
                    }
                    if (message === 'zelda') {
                        var audio2 = new Audio('./musique/Breath of the Wild - Main Theme.mp3');
                        audio2.play();
                    }

                    db.ref('users/' + name + '/messageCount').once('value', function (countSnapshot) {
                        var count = countSnapshot.val() || 0;
                        count++;
                        db.ref('users/' + name + '/messageCount').set(count);
                    });

                    db.ref(servp + '/').once('value', function (message_object) {
                        var timestamp = new Date().toLocaleString();
                        var index = parseFloat(message_object.numChildren()) + 1
                        db.ref(servp + '/' + `message_${index}`).set({
                            name: parent.get_name(),
                            message: message,
                            timestamp: timestamp,
                            index: index
                        })
                            .then(function () {

                                parent.refresh_chat()
                            });

                    });

                });
            });
        }

