                    setTimeout(function () {
                        alert('Nouvelle fonctiannalités : nouvelles écritures,modification du mot de passe, redimention du chat, ajoute de la popup de mis a jour (celle ci),modification de l\'animation de chargement, envoie d\'image par lien termient par .png,.jpg/e,.webp,.gif....');
